import { SourceFileFilter } from '@eloqnt/extractor/_internal';

class SourceFileWatcher {
  subscriptions = [];
  constructor(roots, onChange) {
    this.roots = roots;
    this.onChange = onChange;
  }

  // The native binding is loaded on demand, so `next build` and `next start`
  // never pay for it
  load() {
    return this.watcherModule ??= import('@parcel/watcher');
  }
  async start() {
    if (this.subscriptions.length > 0) {
      return;
    }
    const {
      subscribe
    } = await this.load();
    const ignore = SourceFileFilter.IGNORED_DIRECTORIES.map(dir => `**/${dir}/**`);
    for (const root of this.roots) {
      const sub = await subscribe(root, async (err, events) => {
        if (err) {
          console.error(err);
          return;
        }
        await this.onChange(events);
      }, {
        ignore
      });
      this.subscriptions.push(sub);
    }
  }
  async stop() {
    await Promise.all(this.subscriptions.map(sub => sub.unsubscribe()));
    this.subscriptions = [];
  }
  [Symbol.dispose]() {
    void this.stop();
  }
}

export { SourceFileWatcher as default };
